package com.rappistream.orderprocessor.infrastructure.jpa;  import jakarta.persistence.CollectionTable; import jakarta.persistence.Column; import jakarta.persistence.ElementCollection; import jakarta.persistence.Entity; import jakarta.persistence.Id; import jakarta.persistence.JoinColumn; import jakarta.persistence.Table;  import java.time.Instant; import java.util.ArrayList; import java.util.List;  @Entity @Table(name = "orders") public class OrderJpaEntity {      @Id     @Column(name = "order_id", length = 36, nullable = false)     private String orderId;      @Column(name = "customer_id", length = 64, nullable = false)     private String customerId;      @Column(name = "customer_phone", length = 32, nullable = false)     private String customerPhone;      @Column(name = "address", length = 200, nullable = false)     private String address;      @ElementCollection     @CollectionTable(name = "order_items", joinColumns = @JoinColumn(name = "order_id"))     private List<OrderItemEmbeddable> items = new ArrayList<>();      @Column(name = "state", length = 32, nullable = false)     private String state;      @Column(name = "driver_id", length = 64)     private String driverId;      @Column(name = "created_at", nullable = false)     private Instant createdAt;      public OrderJpaEntity() {     }      public String getOrderId() { return orderId; }     public void setOrderId(String orderId) { this.orderId = orderId; }     public String getCustomerId() { return customerId; }     public void setCustomerId(String customerId) { this.customerId = customerId; }     public String getCustomerPhone() { return customerPhone; }     public void setCustomerPhone(String customerPhone) { this.customerPhone = customerPhone; }     public String getAddress() { return address; }     public void setAddress(String address) { this.address = address; }     public List<OrderItemEmbeddable> getItems() { return items; }     public void setItems(List<OrderItemEmbeddable> items) { this.items = items; }     public String getState() { return state; }     public void setState(String state) { this.state = state; }     public String getDriverId() { return driverId; }     public void setDriverId(String driverId) { this.driverId = driverId; }     public Instant getCreatedAt() { return createdAt; }     public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; } }
